mapper.select:
SELECT status, COUNT(*) AS count
FROM task_execution
WHERE deleted = 0

    AND start_time >= #{startTime}


    AND start_time <= #{endTime}

GROUP BY status

SELECT te.*, t.task_name AS taskName, t.task_type AS taskType, t.status AS task_status FROM task_execution te LEFT JOIN task t ON te.task_id = t.id AND t.deleted = 0 WHERE te.deleted = 0
AND ${ew.sqlSegment}
ORDER BY te.start_time DESC
